mapper.select:
SELECT , ci.class_name as className, d.dept_name as departmentName FROM student s LEFT JOIN sys_user u ON s.user_id = u.id LEFT JOIN class_info ci ON s.class_id = ci.id LEFT JOIN department d ON s.department_id = d.id WHERE 1=1
AND s.student_no LIKE CONCAT('%', #{studentNo}, '%')
AND s.real_name LIKE CONCAT('%', #{realName}, '%')
AND s.class_id = #{classId}
AND s.department_id = #{departmentId}
ORDER BY s.create_time DESC LIMIT #{offset}, #{limit}

